    ("A1", 120, "card"), ("A2", 80, "card"), ("A3", 200, "cash"),      # attempt 1
    ("A1", 125, "card"), ("A2", 80, "card"), ("A3", 200, "cash"),      # retry
]
from collections import defaultdict
groups = defaultdict(list)
for r in rows:
    groups[r[0]].append(r)
print(f"rows in table: {len(rows)}; distinct order refs: {len(groups)}")
for ref, rs in sorted(groups.items()):
    if len(rs) > 1:
        identical = len(set(rs)) == 1
        print(f"  {ref}: {len(rs)} rows, {'identical copies' if identical else 'DIFFER'} -> {rs}")

def extract(first, last):
    return [(f"h{h:02d}-{i}", h) for h in range(first, last + 1) for i in (1, 2)]
table = extract(0, 11) + extract(11, 23)
from collections import Counter
rows_per_hour = Counter(h for _, h in table)
ids_per_hour = {}
for eid, h in table:
    ids_per_hour.setdefault(h, set()).add(eid)
print(f"total rows: {len(table)}; distinct event ids: {len({e for e, _ in table})}")
for h in sorted(rows_per_hour):
    flag = "  <-- rows exceed distinct ids" if rows_per_hour[h] > len(ids_per_hour[h]) else ""
    print(f"  hour {h:02d}: rows={rows_per_hour[h]} distinct_ids={len(ids_per_hour[h])}{flag}")

regions = {"North": [100, 300], "South": [50] * 8}
avgs = {}
for name, amounts in regions.items():
    avgs[name] = sum(amounts) / len(amounts)
    print(f"  {name}: n={len(amounts)} sum={sum(amounts)} avg={avgs[name]:.2f}")
dashboard = sum(avgs.values()) / len(avgs)
all_orders = [a for amounts in regions.values() for a in amounts]
true_avg = sum(all_orders) / len(all_orders)
print(f"dashboard (average of regional averages): {dashboard:.2f}")
print(f"true average over all {len(all_orders)} orders:    {true_avg:.2f}")

